// ─────────────────────────────────────────────────────────────────────────
//  02 · concurrency token to 409★★☆ core
//  concepts: optimistic concurrency · WHERE version = original · 409 Conflict
// ─────────────────────────────────────────────────────────────────────────
//
//  The original version goes into the WHERE clause; zero rows affected means someone got there first.

using static Bootcamp.Check;

int SaveOrder(Db db, int id, string status, int originalVersion)
{
    // UPDATE Orders SET Status = @status, Version = Version + 1 WHERE Id = @id AND Version = @originalVersion
    if (!db.Orders.TryGetValue(id, out var row) || row.Version != originalVersion)
        throw new DbUpdateConcurrencyException("The database operation was expected to affect 1 row(s), but actually affected 0 row(s).");
    db.Orders[id] = new Row(status, row.Version + 1);
    return row.Version + 1;
}

(int Status, int? Version) PutOrder(Db db, int id, string status, int ifMatchVersion)
{
    if (!db.Orders.ContainsKey(id)) return (404, null);
    try
    {
        return (200, SaveOrder(db, id, status, ifMatchVersion));
    }
    catch (DbUpdateConcurrencyException)
    {
        return db.Orders.TryGetValue(id, out var current) ? (409, current.Version) : (409, null);
    }
}

